// Deterministic football choreography in field coordinates. No game-state mutation.
export const limit=(v,a,b)=>Math.max(a,Math.min(b,v));
export const mix=(a,b,t)=>a+(b-a)*t;
export const smooth=(a,b,t)=>{let x=limit((t-a)/(b-a),0,1);return x*x*(3-2*x)};
export function sampleRoute(keys,t){if(t<=keys[0].t)return {...keys[0]};for(let i=1;i<keys.length;i++){let b=keys[i],a=keys[i-1];if(t<=b.t){let u=(t-a.t)/(b.t-a.t),dt=b.t-a.t,prev=keys[Math.max(0,i-2)],next=keys[Math.min(keys.length-1,i+1)];const slope=(p,q,k)=>(q[k]-p[k])/Math.max(.001,q.t-p.t);let out={};for(let k of ['x','z']){let v=slope(a,b,k),v0=(a[k]===prev[k]||i===1)?0:(slope(prev,a,k)+v)*.5,v1=(next[k]===b[k]||i===keys.length-1)?0:(v+slope(b,next,k))*.5;if(v===0)v0=v1=0;v0=Math.sign(v)*Math.min(Math.abs(v0),3*Math.abs(v));v1=Math.sign(v)*Math.min(Math.abs(v1),3*Math.abs(v));out[k]=(2*u*u*u-3*u*u+1)*a[k]+(u*u*u-2*u*u+u)*dt*v0+(-2*u*u*u+3*u*u)*b[k]+(u*u*u-u*u)*dt*v1}return out}}return {...keys.at(-1)}}

const key=(t,x,z)=>({t,x:limit(x,-59,59),z:limit(z,-25,25)});
export function planFootball(before,after,last,start){if(last.execution)return executionPlan(before,after,last);const dir=before.poss===0?1:-1;const penalty=!!last.penalty,kick=['Punt','Field goal'].includes(last.call),sack=/sacked/.test(last.text),pass=!!last.passing&&!sack&&!kick;const incomplete=/incomplete|miss/.test(last.text),turnover=/INTERCEPTED|fumble/.test(last.text),touchdown=/TOUCHDOWN/.test(last.text);let endX=before.poss===0?last.spot-50:50-last.spot;if(incomplete&&pass)endX=limit(start[0].x+dir*(last.call==='Deep pass'?28:15),-56,56);if(kick)endX=last.call==='Field goal'?dir*60:(after.poss===0?after.spot-50:50-after.spot);const carrier=sack?0:pass?2:1;let targetZ=pass?start[2].z+dir*(last.call==='Screen'?4:9):last.call==='Outside run'?dir*11:dir*2;
let routes=start.map(p=>[key(0,p.x,p.z),key(1,p.x,p.z)]);
for(let i=0;i<11;i++){let p=start[i];if(i>=5&&i<=9){routes[i]=[key(0,p.x,p.z),key(.13,p.x,p.z),key(.28,p.x+dir*.65,p.z),key(.80,p.x+dir*1.2,p.z+(i-7)*.12),key(1,p.x+dir*1.2,p.z)];continue}if(i===0){routes[i]=[key(0,p.x,p.z),key(.12,p.x,p.z),key(.28,p.x-dir*(pass?2.5:.5),p.z),key(.42,p.x-dir*(pass?1.8:0),p.z+.3),key(1,p.x-dir*(pass?1.8:0),p.z+.3)];continue}let end=i===carrier?{x:endX,z:targetZ}:{x:limit(p.x+dir*(pass?18:5),-56,56),z:p.z};routes[i]=[key(0,p.x,p.z),key(.12,p.x,p.z),key(.3,p.x+dir*2,p.z),key(.6,end.x-dir*3,end.z),key(.87,end.x,end.z),key(1,end.x,end.z)]}
if(pass){let p=start[carrier],catchX=endX-dir*(incomplete?0:Math.min(3,Math.abs(endX-p.x)*.15));routes[carrier]=[key(0,p.x,p.z),key(.13,p.x,p.z),key(.3,p.x+dir*3,p.z),key(.48,p.x+(catchX-p.x)*.52,p.z),key(.68,catchX,targetZ),key(.87,endX,targetZ),key(1,endX,targetZ)];}
if(!pass&&!kick){let p=start[carrier];let juke=last.animation==='juke'||last.call==='Outside run';routes[carrier]=[key(0,p.x,p.z),key(.12,p.x,p.z),key(.26,start[0].x+dir*.7,2*dir),key(.44,mix(start[0].x,endX,.4),juke?targetZ-4*dir:targetZ),key(.51,mix(start[0].x,endX,.45),juke?targetZ-4*dir:targetZ),key(.62,mix(start[0].x,endX,.62),targetZ),key(.87,endX,targetZ),key(1,endX,targetZ)]}
for(let i=11;i<22;i++){let p=start[i];if(i<15){routes[i]=[key(0,p.x,p.z),key(.12,p.x,p.z),key(.29,p.x-dir*.9,p.z),key(.82,p.x-dir*1.3,p.z),key(1,p.x-dir*1.3,p.z)];}else{let early={x:p.x+dir*(pass?3:-1),z:p.z};let near={x:endX-dir*(i===18?.65:2+(i%3)),z:targetZ+(i===18?.5:(i%3-1)*2.2)};routes[i]=[key(0,p.x,p.z),key(.14,p.x,p.z),key(.36,early.x,early.z),key(.66,mix(early.x,near.x,.6),mix(early.z,near.z,.6)),key(.88,near.x,near.z),key(1,near.x,near.z)]}}
if(sack){routes[0]=[key(0,start[0].x,0),key(.16,start[0].x,0),key(.5,endX,0),key(1,endX,0)];routes[18]=[key(0,start[18].x,start[18].z),key(.65,endX-dir*.5,.5),key(1,endX-dir*.5,.5)]}
if(penalty)routes=start.map(p=>[key(0,p.x,p.z),key(1,p.x,p.z)]);
return {before,after,last,start,routes,carrier,dir,pass,kick,sack,incomplete,turnover,touchdown,penalty,endX,targetZ,release:.43,catchTime:.68,contact:.88};}
export function footballFrame(plan,t,duration=8){if(plan.execution)return executionFrame(plan,t);t=limit(t,0,1);return plan.routes.map((route,i)=>{let p=sampleRoute(route,t),prev=sampleRoute(route,Math.max(0,t-.005)),next=sampleRoute(route,Math.min(1,t+.005));let dt=(Math.min(1,t+.005)-Math.max(0,t-.005))*duration;let vx=(next.x-prev.x)/Math.max(.001,dt),vz=(next.z-prev.z)/Math.max(.001,dt);let speed=Math.hypot(vx,vz),yaw=speed>.04?Math.atan2(vx,vz):(i<11?plan.dir*Math.PI/2:-plan.dir*Math.PI/2);let distance=0;for(let j=1;j<route.length;j++){let a=route[j-1],b=route[j];if(t<=a.t)break;distance+=Math.hypot(b.x-a.x,b.z-a.z)*limit((t-a.t)/(b.t-a.t),0,1)}return {x:p.x,z:p.z,speed,yaw,distance}})}
// Two-bone sagittal IK. Feet stay planted on the stance half of each stride.
export function legPose(distance,speed,side){let phase=(distance/1.6+(side? .5:0))%1,active=limit(speed/.7,0,1),x,y;if(phase<.6){x=mix(.45,-.45,phase/.6)*active;y=-.79}else{let u=(phase-.6)/.4;x=mix(-.45,.45,smooth(0,1,u))*active;y=-.79+Math.sin(Math.PI*u)*.32*active}let l1=.43,l2=.40,d=limit(Math.hypot(x,y),.1,l1+l2-.005),knee=Math.PI-Math.acos(limit((l1*l1+l2*l2-d*d)/(2*l1*l2),-1,1)),hip=Math.atan2(-x,-y)-Math.acos(limit((l1*l1+d*d-l2*l2)/(2*l1*d),-1,1));return {hip,knee,ankle:-hip-knee,phase,plant:phase<.6,footHeight:y+.79}}

function executionPlan(before,after,last){let e=last.execution,dir=before.poss===0?1:-1,frames=e.frames.map(f=>({time:f.time/e.duration,actors:f.actors.map(a=>({...a,x:(a.x-50)*dir,z:a.z*dir,yaw:a.yaw+(dir===-1?Math.PI:0)})),ball:{x:(f.ball.x-50)*dir,y:f.ball.y,z:f.ball.z*dir}}));let release=e.events.find(x=>x.type==='PassReleased'||x.type==='Kick')?.time/e.duration,catchTime=e.events.find(x=>['CatchCompleted','PassIncomplete','Interception'].includes(x.type))?.time/e.duration;release=Number.isFinite(release)?release:.32;catchTime=Number.isFinite(catchTime)?catchTime:Math.min(.78,release+.28);return {before,after,last,execution:e,frames,start:frames[0].actors,routes:frames[0].actors.map((_,i)=>frames.map(f=>({t:f.time,x:f.actors[i].x,z:f.actors[i].z}))),carrier:e.result.carrier,dir,pass:e.result.passing&&e.result.kind!=='sack',kick:['punt','fieldGoal','missedFieldGoal'].includes(e.result.kind),sack:e.result.kind==='sack',incomplete:e.result.kind==='incomplete',turnover:e.result.kind==='interception',touchdown:e.result.kind==='touchdown',penalty:false,endX:(e.result.spot-50)*dir,targetZ:frames.at(-1).actors[e.result.carrier].z,release,catchTime,contact:.88};}
export function executionFrame(plan,t){let b=plan.frames.findIndex(f=>f.time>=t);if(b<0)b=plan.frames.length-1;let right=plan.frames[b],left=plan.frames[Math.max(0,b-1)],u=limit((t-left.time)/Math.max(.0001,right.time-left.time),0,1);return left.actors.map((a,i)=>{let q=right.actors[i],angle=Math.atan2(Math.sin(q.yaw-a.yaw),Math.cos(q.yaw-a.yaw));return {x:mix(a.x,q.x,u),z:mix(a.z,q.z,u),speed:mix(a.speed,q.speed,u),distance:mix(a.distance,q.distance,u),yaw:a.yaw+angle*u}})}
export function executionBall(plan,t){let b=plan.frames.findIndex(f=>f.time>=t);if(b<0)b=plan.frames.length-1;let right=plan.frames[b],left=plan.frames[Math.max(0,b-1)],u=limit((t-left.time)/Math.max(.0001,right.time-left.time),0,1);return {x:mix(left.ball.x,right.ball.x,u),y:mix(left.ball.y,right.ball.y,u),z:mix(left.ball.z,right.ball.z,u)}}
